def c_autoajuste_acotado_1(P, ctx, mod):
    aj = float(ctx.get('ajuste') or 1.0)
    nuevo = round(min(1.0, aj), 3)
    ctx['ajuste'] = nuevo
    return P, ctx, {'ajuste': nuevo}

def c_sin_autoajuste_coca_75_sesgo50_dia3(P, ctx, mod):
    a = ctx.get('serieCoca')
    b = mod.get('serieCocaRio')
    if not a or not b:
        return None
    ph = (mod.get('aciertos') or {}).get('por_horizonte') or {}
    pts = [(0, 0.0)]
    for h, v in ph.items():
        if (v.get('n') or 0) >= 30 and v.get('sesgo_m') is not None:
            pts.append((int(h), float(v['sesgo_m'])))
    pts.sort()
    if len(pts) < 3:
        return None
    s_coca = [round(0.25 * float(x) + 0.75 * float(y), 4) for x, y in zip(a, b)]
    c = mod.get('curva_mazar') or {'a': 3.6595, 'b': 0.12497}
    dvdz = c['a'] + c['b'] * max(0.0, float(ctx['cota']) - 2115.0)
    k = dvdz / 0.0864
    corr = []
    for d in range(60):
        if d < 2:
            corr.append(0.0)
        else:
            t0, t1 = d, d + 1
            s0 = pts[-1][1]
            for (h0, v0), (h1, v1) in zip(pts, pts[1:]):
                if t0 <= h1:
                    s0 = v0 + (v1 - v0) * (t0 - h0) / (h1 - h0)
                    break
            s1 = pts[-1][1]
            for (h0, v0), (h1, v1) in zip(pts, pts[1:]):
                if t1 <= h1:
                    s1 = v0 + (v1 - v0) * (t1 - h0) / (h1 - h0)
                    break
            val = -(s1 - s0) * k * 0.5
            corr.append(max(-80.0, min(80.0, val)))
    base = list(ctx.get('memoria') or [])
    n = max(len(base), len(corr))
    out = [round((float(base[i]) if i < len(base) else 0.0) + (corr[i] if i < len(corr) else 0.0), 2) for i in range(n)]
    ctx['ajuste'] = 1.0
    ctx['serieCoca'] = s_coca
    ctx['memoria'] = out
    return P, ctx, {'ajuste': 1.0, 'serieCoca': s_coca, 'memoria': out}

